INSERT INTO answers(id, question_id, text, correct) VALUES ('3ac67e46-5538-49a2-932c-73202336359e','dd1a8b8c-248f-43cf-9633-431b5c9d2bfd','La policía judicial depende de los Jueces, de los Tribunales y del Ministerio Fiscal en sus funciones de averiguación del delito y descubrimiento y aseguramiento del delincuente, en los términos que la ley establezca..',false);
INSERT INTO questions(id, unit_id, text, explanation, difficulty) VALUES ('538b6ddd-068d-4227-b682-e68797677560','11111111-1111-1111-1111-111111111112','Según la Disp. Trans. Sexta, ¿cuál de las siguientes afirmaciones es correcta?','Disp. Trans. Sexta','EASY');
INSERT INTO answers(id, question_id, text, correct) VALUES ('2d1642a3-64a2-415d-ae50-994b2f9dc83a','538b6ddd-068d-4227-b682-e68797677560','Cuando se remitieran a la Comisión Constitucional del Congreso varios proyectos de Estatuto, se dictaminarán por el orden de entrada en aquélla, y el plazo de dos meses a que se refiere el artículo…',true);
INSERT INTO answers(id, question_id, text, correct) VALUES ('d8a8116e-bf23-4456-a4c2-9f3bc4a3b74a','538b6ddd-068d-4227-b682-e68797677560','Todos los españoles tienen los mismos derechos y obligaciones en cualquier parte del territorio del Estado.',false);
INSERT INTO answers(id, question_id, text, correct) VALUES ('6da2f193-f444-4611-84aa-e84d9209922d','538b6ddd-068d-4227-b682-e68797677560','El Tribunal Supremo, con jurisdicción en toda España, es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de garantías constitucionales.',false);
INSERT INTO answers(id, question_id, text, correct) VALUES ('b53156ad-fa1e-4f09-92ed-82e24388fde6','538b6ddd-068d-4227-b682-e68797677560','El Gobierno o cualquiera de las Cámaras puede requerir al Tribunal Constitucional para que declare si existe o no esa contradicción. 41',false);
INSERT INTO questions(id, unit_id, text, explanation, difficulty) VALUES ('92a35ee5-20f4-4b82-9b70-04b3cb0beab3','11111111-1111-1111-1111-111111111112','Según la Disp. Final, ¿cuál de las siguientes afirmaciones es correcta?','Disp. Final','EASY');
INSERT INTO answers(id, question_id, text, correct) VALUES ('4033fb79-eba3-4326-a62f-a573487ca28c','92a35ee5-20f4-4b82-9b70-04b3cb0beab3','Todos tienen derecho a la vida y a la integridad física y moral, sin que, en ningún caso, puedan ser sometidos a tortura ni a penas o tratos inhumanos o degradantes.',false);
INSERT INTO answers(id, question_id, text, correct) VALUES ('e442529e-8d7a-4d1b-a864-4565377a3365','92a35ee5-20f4-4b82-9b70-04b3cb0beab3','Los españoles son iguales ante la ley, sin que pueda prevalecer discriminación alguna por razón de nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social.',false);
INSERT INTO answers(id, question_id, text, correct) VALUES ('227bc893-c051-4ffe-8b87-67b10fafdfa7','92a35ee5-20f4-4b82-9b70-04b3cb0beab3','Esta Constitución entrará en vigor el mismo día de la publicación de su texto oficial en el boletín oficial del Estado.',true);
INSERT INTO answers(id, question_id, text, correct) VALUES ('3bf6941a-0eaa-44ca-9195-45967834be30','92a35ee5-20f4-4b82-9b70-04b3cb0beab3','La soberanía nacional reside en el pueblo español, del que emanan los poderes del Estado.',false);
